namespace Depot.Data;

internal static class FinanceAccountsPayableSchemaInitializer
{
	public static void Ensure(IDatabaseConnectionFactory connectionFactory)
	{
		using var connection = connectionFactory.CreateConnection();
		connection.Open();
		using var command = connection.CreateCommand();
		foreach (var statement in Statements(connectionFactory.Provider))
		{
			command.CommandText = statement;
			command.Parameters.Clear();
			command.ExecuteNonQuery();
		}
	}

	private static IReadOnlyList<string> Statements(DatabaseProvider provider) => provider switch
	{
		DatabaseProvider.Local => LocalStatements,
		DatabaseProvider.SqlServer => SqlServerStatements,
		DatabaseProvider.MySql => MySqlStatements,
		_ => throw new NotSupportedException($"Finance Accounts Payable schema initialization is not supported for provider '{provider}'.")
	};

	private static readonly string[] LocalStatements =
	[
		"CREATE TABLE IF NOT EXISTS FinancePayablesConfigurations (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, SingletonKey INTEGER NOT NULL DEFAULT 1 UNIQUE, LegalEntityId TEXT NOT NULL, FiscalCalendarId TEXT NOT NULL, InvoicePostingProfileId INTEGER NOT NULL, CreditNotePostingProfileId INTEGER NOT NULL, PaymentPostingProfileId INTEGER NOT NULL, IsActive INTEGER NOT NULL);",
		"CREATE TABLE IF NOT EXISTS FinanceSupplierDocuments (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, Kind INTEGER NOT NULL, SupplierId INTEGER NOT NULL, SupplierDocumentNumber TEXT NOT NULL, InternalReference TEXT NULL, DocumentDate TEXT NOT NULL, DueDate TEXT NOT NULL, CurrencyCode TEXT NOT NULL, Status INTEGER NOT NULL, NetAmount NUMERIC NOT NULL, TaxAmount NUMERIC NOT NULL, GrossAmount NUMERIC NOT NULL, CreatedByUserId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, SubmittedByUserId INTEGER NULL, SubmittedAtUtc TEXT NULL, ApprovalDecisionByUserId INTEGER NULL, ApprovalDecisionAtUtc TEXT NULL, ApprovalComment TEXT NULL, MatchExceptionApproved INTEGER NOT NULL DEFAULT 0, MatchExceptionReason TEXT NULL, PostedByUserId INTEGER NULL, PostedAtUtc TEXT NULL, PostingOperationId TEXT NULL UNIQUE, OpenItemId INTEGER NULL, JournalEntryId INTEGER NULL, ReversalOperationId TEXT NULL UNIQUE, ReversalJournalEntryId INTEGER NULL, ReversedAtUtc TEXT NULL, ReversedByUserId INTEGER NULL, UNIQUE(SupplierId,SupplierDocumentNumber,Kind));",
