		"CREATE INDEX IF NOT EXISTS IX_FinanceSupplierDocuments_Supplier ON FinanceSupplierDocuments (SupplierId,DocumentDate,Id);",
		"CREATE TABLE IF NOT EXISTS FinanceSupplierDocumentLines (Id INTEGER PRIMARY KEY AUTOINCREMENT, DocumentId INTEGER NOT NULL, LineNumber INTEGER NOT NULL, PurchaseOrderLineId INTEGER NULL, GoodsReceiptLineId INTEGER NULL, Description TEXT NOT NULL, Quantity NUMERIC NOT NULL, UnitPrice NUMERIC NOT NULL, NetAmount NUMERIC NOT NULL, TaxAmount NUMERIC NOT NULL, GrossAmount NUMERIC NOT NULL, MatchStatus INTEGER NOT NULL, OrderedUnitPrice NUMERIC NULL, ReceivedQuantity NUMERIC NULL, PreviouslyInvoicedQuantity NUMERIC NULL, QuantityVariance NUMERIC NOT NULL DEFAULT 0, PriceVariance NUMERIC NOT NULL DEFAULT 0, UNIQUE(DocumentId,LineNumber));",
		"CREATE INDEX IF NOT EXISTS IX_FinanceSupplierDocumentLines_PurchaseOrderLine ON FinanceSupplierDocumentLines (PurchaseOrderLineId,DocumentId,Id);",
		"CREATE TABLE IF NOT EXISTS FinancePayableOpenItems (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, LegalEntityId TEXT NOT NULL, AccountingBookId TEXT NOT NULL, SupplierId INTEGER NOT NULL, Kind INTEGER NOT NULL, SourceType TEXT NOT NULL, SourceId TEXT NOT NULL, SourceReference TEXT NULL, DocumentDate TEXT NOT NULL, DueDate TEXT NOT NULL, CurrencyCode TEXT NOT NULL, OriginalAmount NUMERIC NOT NULL, RemainingAmount NUMERIC NOT NULL, JournalEntryId INTEGER NOT NULL, OperationId TEXT NOT NULL UNIQUE, IsVoided INTEGER NOT NULL DEFAULT 0, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, UNIQUE(SourceType,SourceId));",
