		"CREATE TABLE IF NOT EXISTS FinancePayableAllocationOperations (OperationId TEXT NOT NULL PRIMARY KEY, RequestHash TEXT NOT NULL, DebitOpenItemId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL);",
		"CREATE TABLE IF NOT EXISTS FinancePayablePayments (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, OperationId TEXT NOT NULL UNIQUE, RequestHash TEXT NOT NULL, SupplierId INTEGER NOT NULL, CurrencyCode TEXT NOT NULL, PaymentDate TEXT NOT NULL, Amount NUMERIC NOT NULL, Reference TEXT NULL, Description TEXT NOT NULL, OpenItemId INTEGER NOT NULL, JournalEntryId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, IsReversed INTEGER NOT NULL DEFAULT 0, ReversalOperationId TEXT NULL UNIQUE, ReversalJournalEntryId INTEGER NULL, ReversedAtUtc TEXT NULL, ReversedByUserId INTEGER NULL);",
		"CREATE INDEX IF NOT EXISTS IX_FinancePayablePayments_Supplier ON FinancePayablePayments (SupplierId,PaymentDate,Id);"
